        linked_node_ids TEXT NOT NULL
    , base_importance REAL NOT NULL DEFAULT 0.5, access_count INTEGER NOT NULL DEFAULT 0, last_access REAL, valid_from REAL, valid_to REAL, lineage_request_id TEXT NOT NULL DEFAULT '');
